style.css:
@-moz-document url-prefix("https://discord.com/") {
/* Main app background */
    body, .appMount-2yBXZl {
        background: url("https://www.todayifoundout.com/wp-content/uploads/2017/11/rick-astley.png") !important;
        background-size: cover !important;
        background-position: center !important;
    }

    /* Make chat & sidebar slightly see-through */
    .sidebar-1tnWFu, 
    .chat-2ZfjoI, 
    .container-2cd8Mz {
        background-color: rgba(0,0,0,0.6) !important;
        backdrop-filter: blur(5px);
    }

    /* Text color for visibility */
    .messageContent-2t3eCI,
    .markup-eYLPri {
        color: #fff !important;
    }
}
